pts=[(0,3),(1,5),(3,2),(3,7),(4,3),(4,6),(8,0),(8,2),(8,5),(9,2),(9,4),(9,5),(14,5),(16,3),(18,6),(19,4),(20,2)]
import math
cells=set(pts)
for i,(r,c) in enumerate(pts):
 for R,C in pts[i+1:]:
  dr,dc=R-r,C-c; g=math.gcd(abs(dr),abs(dc))
  if g>=1:
   for k in range(g+1): cells.add((r+k*(dr//g),c+k*(dc//g)))
grid=[[8 if (r,c) in pts else 3 if (r,c) in cells else 7 for c in range(8)] for r in range(21)]
print(grid)
